static esp_err_t visual_post(httpd_req_t*r){int v;bool changed=false;if(query_int(r,"stroke",&v)){g_visual.stroke=clampi(v,1,24);changed=true;}if(query_int(r,"detail",&v)){g_visual.detail=clampi(v,12,56);changed=true;}if(query_int(r,"complexity",&v)){g_visual.complexity=clampi(v,0,100);changed=true;}if(query_int(r,"multiply",&v)){g_visual.multiply=clampi(v,50,300);changed=true;}if(query_int(r,"speed",&v)){g_visual.speed=clampi(v,0,200);changed=true;}if(query_int(r,"zoom",&v)){g_visual.zoom=clampi(v,50,235);changed=true;}if(query_int(r,"sensitivity",&v)){g_visual.sensitivity=clampi(v,10,200);changed=true;}if(changed)g_visual.rev++;return visual_get(r);}
