void prisma_sensors_web_register(httpd_handle_t s){if(!s)return;gpio_config_t key_cfg={.pin_bit_mask=1ULL<<PRISMA_VISUAL_KEY,.mode=GPIO_MODE_INPUT,.pull_up_en=GPIO_PULLUP_ENABLE,.pull_down_en=GPIO_PULLDOWN_DISABLE,.intr_type=GPIO_INTR_DISABLE};gpio_config(&key_cfg);httpd_uri_t page={.uri="/simple-synth",.method=HTTP_GET,.handler=page_get},legacy={.uri="/sensors",.method=HTTP_GET,.handler=old_page_get},api={.uri="/api/sensors/imu",.method=HTTP_GET,.handler=imu_get},visualg={.uri="/api/sensors/visual",.method=HTTP_GET,.handler=visual_get},visualp={.uri="/api/sensors/visual",.method=HTTP_POST,.handler=visual_post},beep={.uri="/api/sensors/beep",.method=HTTP_POST,.handler=beep_post},vol={.uri="/api/sensors/volume",.method=HTTP_POST,.handler=volume_post},music={.uri="/api/sensors/music",.method=HTTP_POST,.handler=music_post};httpd_register_uri_handler(s,&page);httpd_register_uri_handler(s,&legacy);httpd_register_uri_handler(s,&api);httpd_register_uri_handler(s,&visualg);httpd_register_uri_handler(s,&visualp);httpd_register_uri_handler(s,&beep);httpd_register_uri_handler(s,&vol);httpd_register_uri_handler(s,&music);}
